const test=require('node:test'),assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs'),path=require('node:path');
test('发布插件不依赖 Obsidian 不提供的相对 require',()=>{const context={module:{exports:{}},require:name=>{if(name==='obsidian')return {Plugin:class{},ItemView:class{}};if(name.startsWith('./'))throw Error('Obsidian 外部 require 不解析插件相对模块 '+name);return require(name)}};vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../main.js'),'utf8'),context);assert.equal(typeof context.module.exports,'function');});
test('附件恢复后从磁盘读取，不能依赖尚未更新的文件缓存',async()=>{const context={module:{exports:{}},require:name=>name==='obsidian'?{Plugin:class{},ItemView:class{},TFile:class{}}:require(name)};vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../io.js'),'utf8'),context);assert.equal(typeof context.module.exports.ioFor,'function');const io=context.module.exports.ioFor({vault:{getFiles:()=>[],adapter:{async list(p){return p===''?{files:[],folders:['90 附件']}:{files:['90 附件/已恢复.pdf'],folders:[]}},async stat(){return {size:612}}}}});const list=await io.list();assert.equal(list.length,1);assert.equal(list[0].path,'90 附件/已恢复.pdf');});
